import { useEffect, useState } from "react";
import manifest from "@/image-manifest.json";
import { projects, work } from "@/content";

// Generated by `npm run images` from the files in images/.
type ImageInfo = { base: string; width: number; height: number; widths: number[] };
const images: Record<string, ImageInfo> = manifest;

/**
 * How wide each kind of image shows, so the browser can pick the smallest file that's still
 * sharp. Above 1440px the layout scales with the screen (see index.css), hence the vw values.
 */
export const SIZES = {
  portrait: "(min-width: 1440px) 13vw, 200px",
  shot: "(min-width: 1440px) 26vw, (min-width: 720px) 400px, calc(100vw - 72px)",
  strip: "(min-width: 1440px) 15vw, (min-width: 720px) 230px, calc(58vw - 40px)",
};

const srcSet = (img: ImageInfo, ext: "avif" | "webp") =>
  img.widths.map((w) => `${img.base}-${w}.${ext} ${w}w`).join(", ");

/** An optimised image: AVIF where supported, WebP otherwise, at the right size for the screen. */
export function Picture({
  src,
  alt,
  sizes,
  className,
  loading,
  fetchPriority,
}: {
  src: string;
  alt: string;
  sizes: string;
  className?: string;
  loading?: "eager" | "lazy";
  fetchPriority?: "high" | "low" | "auto";
}) {
  const img = images[src];
  if (!img) throw new Error(`No optimised image for ${src}. Add it to images/ and run npm run images.`);
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(img, "avif")} sizes={sizes} />
      <img
        className={className}
        src={`${img.base}-${img.widths.at(-1)}.webp`}
        srcSet={srcSet(img, "webp")}
        sizes={sizes}
        alt={alt}
        width={img.width}
        height={img.height}
        loading={loading}
        fetchPriority={fetchPriority}
        decoding="async"
      />
    </picture>
  );
}

/**
 * Once the page is idle, quietly downloads every image at the size this screen would use, so
 * pages open with their images ready. Skipped when the visitor has asked to save data.
 * Hidden images still download, and the browser picks the same file it will pick later.
 */
export function PreloadImages() {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const connection = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
    if (connection?.saveData) return;
    // Safari has no requestIdleCallback everywhere yet, so fall back to a short delay.
    const hasIdle = typeof window.requestIdleCallback === "function";
    let handle = 0;
    const start = () => {
      handle = hasIdle
        ? window.requestIdleCallback(() => setReady(true), { timeout: 3000 })
        : window.setTimeout(() => setReady(true), 1500);
    };
    if (document.readyState === "complete") start();
    else window.addEventListener("load", start, { once: true });
    return () => {
      window.removeEventListener("load", start);
      if (hasIdle) window.cancelIdleCallback(handle);
      else window.clearTimeout(handle);
    };
  }, []);

  if (!ready) return null;
  return (
    <div hidden aria-hidden="true">
      <Picture src="/about/dean.jpg" alt="" sizes={SIZES.portrait} fetchPriority="low" />
      {[...work, ...projects].flatMap((entry) =>
        entry.pictures.map((pic) => (
          <Picture
            key={pic.src}
            src={pic.src}
            alt=""
            sizes={entry.pictures.length === 1 ? SIZES.shot : SIZES.strip}
            fetchPriority="low"
          />
        )),
      )}
    </div>
  );
}
